import json, re, subprocess
from pathlib import Path
head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
rows=[x for x in json.loads(Path('/home/drx/.cache/mipstarre-dev/palomar/module-packets.json').read_text())['files'] if x['packet']==6]
patterns={
  'proof_debt': re.compile(r'\\b(sorry|axiom|admit)\\b'),
  'bypass': re.compile(r'\\b(native_decide|unsafeCast|unsafeCoerce|lcProof|ofReduceBool|ofReduceNat)\\b'),
  'meta_api': re.compile(r'("'^|'"\\s)(elab|macro|syntax|command_elab|term_elab|tactic|initialize|builtin_initialize|open Lean|namespace Lean)(\\s|"'$)'"', re.M),
}
for label,pattern in patterns.items():
    hits=[]
    for row in rows:
        text=subprocess.check_output(['git','show',f'{head}:{row[\"path\"]}'],text=True)
